class ServiceReferenceRenderingTest {
	private static final String NESTED = "SELECT ?o WHERE { SERVICE SILENT ?outer { <_:outer> <urn:p> ?o . "
			+ "SERVICE SILENT <urn:inner> { <_:inner> <urn:q> ?o } } }";

	@Test
	void legacyNestedServicesRetainSilentAndVariableEndpointScopes() throws Exception {
		var parsed = parse(NESTED);
		assertServiceScopes(parsed, parse(new SPARQLQueryRenderer().render(parsed)));
	}

	@Test
	void experimentalNestedServicesRetainSilentAndVariableEndpointScopes() throws Exception {
		var parsed = parse(NESTED);
		assertServiceScopes(parsed, parse(new SparqlQueryRenderer().render(parsed)));
	}

	@Test
	void legacyComposedReferencesAndAnonymousControlsRemainRemoteOwned() throws Exception {
		var parsed = parse("PREFIX ex:<urn:> SELECT ?o WHERE { SERVICE SILENT ?outer { "
				+ "GRAPH <_:graph> { <_:outer> ex:p <<(<_:component> ex:q ?o)>> . [] ex:r ?o . "
				+ "SERVICE SILENT <urn:inner> { <_:inner> ex:q ?o } } } }");
		assertServiceScopes(parsed, parse(new SPARQLQueryRenderer().render(parsed)));
	}

	private static ParsedQuery parse(String source) {
		return QueryParserUtil.parseQuery(QueryLanguage.SPARQL, source, null);
	}

	private static void assertServiceScopes(ParsedQuery first, ParsedQuery second) {
		assertEquals(Set.of(), second.getReservedBNodeIDs(), "SERVICE-owned IDs must not become local references");
		assertEquals(describe(first), describe(second));
	}

	private static List<Scope> describe(ParsedQuery parsed) {
		var result = new ArrayList<Scope>();
		parsed.getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Service node) {
				String endpoint = node.getServiceRef().hasValue() ? node.getServiceRef().getValue().stringValue()
						: "?" + node.getServiceRef().getName();
				result.add(new Scope(endpoint, node.isSilent(), node.getReservedBNodeIDs(), node.getServiceVars()));
				super.meet(node);
			}
		});
		return result;
	}

	private record Scope(String endpoint, boolean silent, Set<String> ownedIds, Set<String> variables) {
	}
}
